import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Works out the move a status change makes. A clerk settling an OPEN claim whose due is above the
 *  sheet's clerk limit sends it to PENDING instead. A claim whose due is n/a is within any limit; a
 *  sheet with no limit, and a steward, settle anything. Only a steward reviews a PENDING claim, and
 *  only a review moves it to SETTLED or back to OPEN; a review of a claim that is not PENDING is refused.
 *  Before the limit is considered, settling or approving a claim with no proofs whose due is above the
 *  proof threshold is refused (see {@link CheckProofs}), so it never goes to PENDING. Opening, settling
 *  and voiding are refused to a role the sheet's permission matrix does not allow it. */
public class CheckClerkLimit {
    public void check(@Val StatusInput input, @Val Claim claim, RoleStore roles, SettingStore settings,
            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims, Out<StatusMove> move)
            throws InvalidSheetException {
        ClaimStatus from = claim.getStatus();
        Role role = roles.find(claim.getSheetId(), input.user());
        boolean steward = role == Role.STEWARD;
        if (input.review()) {
            if (from != ClaimStatus.PENDING) {
                throw new InvalidSheetException("Only a PENDING claim can be approved or rejected");
            }
            if (!steward) {
                throw new InvalidSheetException("Only a steward can approve or reject a claim");
            }
            CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
            move.set(new StatusMove(from, input.status()));
            return;
        }
        if (from == ClaimStatus.PENDING && input.status() != ClaimStatus.VOID) {
            throw new InvalidSheetException("A PENDING claim waits for a steward to approve or reject it");
        }
        refuseUnpermitted(input.status(), claim.getSheetId(), role, settings);
        CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
        move.set(new StatusMove(from, overLimit(input, claim, steward, settings, people, rates, sheets, claims)
                ? ClaimStatus.PENDING : input.status()));
    }

    /** Refuses opening, settling or voiding a claim by a role the sheet's permission matrix does not allow it. */
    static void refuseUnpermitted(ClaimStatus to, String sheetId, Role role, SettingStore settings)
            throws InvalidSheetException {
        String action = to == ClaimStatus.OPEN ? "open" : to == ClaimStatus.SETTLED ? "settle"
                : to == ClaimStatus.VOID ? "void" : null;
        if (action != null && !settings.allows(sheetId, action, role)) {
            throw new InvalidSheetException("A " + role.shown() + " may not " + action + " a claim");
        }
    }

    private static boolean overLimit(StatusInput input, Claim claim, boolean steward, SettingStore settings,
            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims) {
        if (input.status() != ClaimStatus.SETTLED || claim.getStatus() != ClaimStatus.OPEN || steward) {
            return false;
        }
        BigDecimal limit = settings.clerkLimit(claim.getSheetId());
        if (limit == null) {
            return false;
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims).due(claim, pct);
        return due != null && due.compareTo(limit) > 0;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim on a sheet. {@code amount} has two decimals and is 0.00 or more, or negative for
 *  a correction, which names the number of the settled claim of its person it corrects; it starts
 *  as {@link ClaimStatus#DRAFT}. */
public class Claim {
    private final long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private boolean statedNa;
    private String corrects;
    private final LocalDate dueBy;
    private LocalDate deferredUntil;
    private int proofs;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
            BigDecimal statedDue, String corrects, LocalDate dueBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
        this.corrects = corrects;
        this.dueBy = dueBy;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public LocalDate getDate() { return date; }
    public String getNote() { return note; }
    public ClaimStatus getStatus() { return status; }
    /** The number given when the claim was opened (the sheet-wide 1, 2, ..., or <period>-<n> / X-<n>
     *  while the sheet numbers by period); null for a draft, or a claim voided as a draft;
     *  a claim voided once open keeps it. */
    public String getNumber() { return number; }
    /** The due fixed when the claim was settled; null when not settled, or settled with no rate. */
    public BigDecimal getSettledDue() { return settledDue; }
    /** The user who opened the claim; null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    /** Whether the person's last statement bound the claim to its figure then. */
    public boolean isStated() { return stated; }
    /** The figure the claim was bound to by the person's last statement; null when it had none (n/a)
     *  or is not bound. */
    public BigDecimal getStatedDue() { return statedDue; }
    /** Whether the person's last statement bound the claim to n/a: the rate that would apply to it had
     *  ended (its to-date) before the claim's date. */
    public boolean isStatedNa() { return statedNa; }
    /** Whether the claim keeps the figure its person's last statement bound it to (a figure, or n/a when
     *  {@link #isStatedNa()}): not while it is PENDING, when it follows its live figure (it is bound
     *  again if rejected back to OPEN). */
    public boolean isBound() { return stated && (statedDue != null || statedNa) && status != ClaimStatus.PENDING; }
    /** The number of the claim this correction corrects; null when it is not a correction. */
    public String getCorrects() { return corrects; }
    /** Whether the claim is a correction: a negative amount, with no floor and no late charge. */
    /** The date the claim is due by, fixed when it was added; later changes to the terms or its date
     *  leave it as it is. */
    public LocalDate getDueBy() { return dueBy; }
    public boolean isCorrection() { return amount.signum() < 0; }
    /** The date the claim was last deferred until; null when it was never deferred. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    /** Whether the claim is deferred on {@code today}: OPEN and deferred until a date after it. Until
     *  then it counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }
    /** How many proofs the claim has; a claim due above the sheet's proof threshold on its date cannot be
     *  settled or approved while it has none (see {@link CheckProofs}). */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    public void setPersonId(long personId) { this.personId = personId; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public void setDate(LocalDate date) { this.date = date; }
    public void setNote(String note) { this.note = note; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    public void setNumber(String number) { this.number = number; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    public void setStated(boolean stated) { this.stated = stated; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    public void setStatedNa(boolean statedNa) { this.statedNa = statedNa; }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims kept per sheet, newest first: by when each was added, or moved to its person. */
@Repository
public class ClaimStore {

    private static final RowMapper<Claim> ROW = (rs, i) -> {
        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"),
            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
            rs.getString("number"), rs.getBigDecimal("settled_due"),
            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
            rs.getString("corrects"), rs.getObject("due_by", LocalDate.class));
        claim.setStatedNa(rs.getBoolean("stated_na"));
        claim.setDeferredUntil(rs.getObject("deferred_until", LocalDate.class));
        claim.setProofs(rs.getInt("proofs"));
        return claim;
    };

    private final JdbcTemplate jdbc;

    public ClaimStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY listed DESC", ROW, sheetId);
    }

    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person's claim with the number, or null when they have none. */
    public Claim findByNumber(String sheetId, long personId, String number) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?", ROW,
                sheetId, personId, number);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Adds a draft claim due by {@code dueBy}, which stays as it is whatever later changes. */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setString(6, corrects);
            ps.setDate(7, Date.valueOf(dueBy));
            return ps;
        }, keys);
        return new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null, false, null,
                corrects, dueBy);
    }

    public void save(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ? "
                + "WHERE sheet_id = ? AND id = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
                claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getSheetId(), claim.getId());
    }

    /** Stores a draft's amount, date, note and the claim it corrects; false when the stored claim is no longer a draft. */
    public boolean edit(Claim claim) {
        return jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, corrects = ? WHERE sheet_id = ? AND id = ? AND status = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getCorrects(), claim.getSheetId(), claim.getId(),
                ClaimStatus.DRAFT.name()) == 1;
    }

    /** The person's claims, newest first, their rows locked until the transaction ends. */
    public List<Claim> listForUpdate(String sheetId, long personId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC FOR UPDATE",
                ROW, sheetId, personId);
    }

    /** Binds the claim to the figure (null for n/a), or unbinds it when not {@code stated}. */
    public void bind(Claim claim) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ?, stated_na = ? WHERE sheet_id = ? AND id = ?",
                claim.isStated(), claim.getStatedDue(), claim.isStatedNa(), claim.getSheetId(), claim.getId());
    }

    /** Defers the stored OPEN claim until the date; false when it is no longer OPEN (another user moved it on). */
    public boolean defer(Claim claim, LocalDate until) {
        boolean deferred = jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet_id = ? AND id = ? AND status = ?",
                Date.valueOf(until), claim.getSheetId(), claim.getId(), ClaimStatus.OPEN.name()) == 1;
        if (deferred) {
            claim.setDeferredUntil(until);
        }
        return deferred;
    }

    /** Raises the stored DRAFT, OPEN or PENDING claim's proofs count by one; false when it is no longer one of
     *  those (another user moved it on). */
    public boolean addProof(Claim claim) {
        boolean added = jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet_id = ? AND id = ? AND status IN (?, ?, ?)",
                claim.getSheetId(), claim.getId(), ClaimStatus.DRAFT.name(), ClaimStatus.OPEN.name(),
                ClaimStatus.PENDING.name()) == 1;
        if (added) {
            claim.setProofs(jdbc.queryForObject("SELECT proofs FROM claim WHERE sheet_id = ? AND id = ?", Integer.class,
                    claim.getSheetId(), claim.getId()));
        }
        return added;
    }

    /** Moves the stored DRAFT, OPEN or PENDING claim to the person, unbound from any statement figure and
     *  listed as their newest claim; false when it is no longer one of those (another user moved it on). */
    public boolean reassign(Claim claim, long personId) {
        boolean moved = jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE, "
                + "listed = NEXT VALUE FOR claim_listed_seq WHERE sheet_id = ? AND id = ? AND status IN (?, ?, ?)",
                personId, claim.getSheetId(), claim.getId(), ClaimStatus.DRAFT.name(), ClaimStatus.OPEN.name(),
                ClaimStatus.PENDING.name()) == 1;
        if (moved) {
            claim.setPersonId(personId);
            claim.setStated(false);
            claim.setStatedDue(null);
            claim.setStatedNa(false);
        }
        return moved;
    }

    /** Moves the stored claim from {@code from} to {@code to}, locking its row until the transaction
     *  ends; false when it is no longer {@code from} (another user moved it first). */
    public boolean move(Claim claim, ClaimStatus from, ClaimStatus to) {
        return jdbc.update("UPDATE claim SET status = ? WHERE sheet_id = ? AND id = ? AND status = ?", to.name(),
                claim.getSheetId(), claim.getId(), from.name()) == 1;
    }

    /** Takes the next claim number on the sheet: 1, then 2, and so on. The sheet's counter row stays
     *  locked until the transaction ends, so a number is never given twice, and is not used up if
     *  the transaction rolls back. */
    public long nextNumber(String sheetId) {
        try {
            jdbc.update("INSERT INTO claim_number (sheet_id, last_number) SELECT ?, 0 FROM DUAL "
                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_number WHERE sheet_id = ?)", sheetId, sheetId);
        } catch (DataAccessException e) {
            // another transaction added the sheet's counter first
        }
        jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet_id = ?", sheetId);
        return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet_id = ?", Long.class, sheetId);
    }

    /** Takes the next number in one of the sheet's per-period sequences: 1, then 2, and so on, locked
     *  as {@link #nextNumber(String)} is. */
    public long nextNumber(String sheetId, String sequence) {
        try {
            jdbc.update("INSERT INTO claim_period_number (sheet_id, sequence, last_number) SELECT ?, ?, 0 FROM DUAL "
                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_period_number WHERE sheet_id = ? AND sequence = ?)",
                    sheetId, sequence, sheetId, sequence);
        } catch (DataAccessException e) {
            // another transaction added the sequence's counter first
        }
        jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND sequence = ?",
                sheetId, sequence);
        return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet_id = ? AND sequence = ?",
                Long.class, sheetId, sequence);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodResponse;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;

/** The number a claim receives when opened. While the sheet's period-numbering-from is set and the
 *  sheet's today is on or after it, the claim is numbered within the period its date falls in,
 *  <period name>-<n> counting from 1 in each period, or X-<n> in its own sequence when it falls in
 *  none. Otherwise it takes the sheet's next sheet-wide number (1, 2, ...), which carries on from
 *  where it left off. */
public final class Numbering {

    /** The sequence of claims dated in no period. */
    private static final String NO_PERIOD = "X";

    private Numbering() {
    }

    public static String next(String sheetId, LocalDate claimDate, ClaimStore claims, SettingStore settings,
            SheetStore sheets, PeriodStore periods) {
        LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            return String.valueOf(claims.nextNumber(sheetId));
        }
        PeriodResponse period = periods.on(sheetId, claimDate);
        if (period == null) {
            return NO_PERIOD + "-" + claims.nextNumber(sheetId, NO_PERIOD);
        }
        return period.name() + "-" + claims.nextNumber(sheetId, "P:" + period.name());
    }
}

