package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    /** A number with up to two decimals; negative for a correction. */
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    /** A claim number: the sheet-wide 1, 2, ... or <period>-<n> / X-<n>. */
    private static final Pattern NUMBER = Pattern.compile("\\S{1,255}");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimRequest request,
            SheetStore sheets, Out<ClaimInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseViewer(sheetId.trim(), request == null ? null : request.user());
        body.set(check(sheetId, request, sheets));
    }

    /** The claim form's rules on a typed claim, before anything is stored: the claim as it would be stored. */
    static ClaimInput check(String sheetId, ClaimRequest request, SheetStore sheets) throws InvalidSheetException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number with up to two decimals");
        }
        String dateText = request.date() == null ? "" : request.date().trim();
        LocalDate date;
        try {
            date = dateText.isEmpty() ? sheets.today(sheetId.trim()) : LocalDate.parse(dateText);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + dateText);
        }
        String note = request.note() == null ? "" : request.note().trim();
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String correctsText = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (!NUMBER.matcher(correctsText).matches()) {
                throw new InvalidSheetException("A negative amount must name the number of the settled claim it corrects");
            }
            corrects = correctsText;
        } else if (!correctsText.isEmpty()) {
            throw new InvalidSheetException("Only a negative amount corrects a claim");
        }
        return new ClaimInput(value, date, note, request.user(), corrects);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each claim's status log, oldest first: a line per status it has had,
 *  {@code <STATUS> by <user> on <sheet's today> due=<due as computed then, n/a when no rate applied>}. */
@Repository
public class ClaimLogStore {

    private final JdbcTemplate jdbc;
    private final ClaimStore claims;
    private final PersonStore people;
    private final RateStore rates;
    private final SettingStore settings;
    private final SheetStore sheets;

    public ClaimLogStore(JdbcTemplate jdbc, ClaimStore claims, PersonStore people, RateStore rates,
            SettingStore settings, SheetStore sheets) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Logs the claim's current status, by the user, on the sheet's today, at its due as the screen
     *  works it out now (its settled due once settled, else its figure plus any late charge). */
    public void record(Claim claim, String user) {
        String sheetId = claim.getSheetId();
        LocalDate today = sheets.today(sheetId);
        Person person = people.find(sheetId, claim.getPersonId());
        BigDecimal pct = person == null ? null
                : rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(sheetId, settings, sheets, claims).due(claim, pct);
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, claim.getId(), claim.getStatus().name(), user, Date.valueOf(today),
                due == null ? "n/a" : due.setScale(2).toPlainString());
    }

    /** Every claim's log lines on the sheet, by claim id, oldest first. */
    public Map<Long, List<String>> lines(String sheetId) {
        Map<Long, List<String>> lines = new HashMap<>();
        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            lines.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + rs.getObject("log_date", LocalDate.class) + " due=" + rs.getString("due"));
        }, sheetId);
        return lines;
    }

    /** Each claim's status at the end of the date, by claim id, as its log records it: the last status
     *  logged on or before the date. A claim logged only after it (added after it) is absent. */
    public Map<Long, ClaimStatus> statusesAt(String sheetId, LocalDate date) {
        Map<Long, ClaimStatus> statuses = new HashMap<>();
        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND log_date <= ? ORDER BY id", rs -> {
            statuses.put(rs.getLong("claim_id"), ClaimStatus.valueOf(rs.getString("status")));
        }, sheetId, Date.valueOf(date));
        return statuses;
    }

    /** The claim's log lines, oldest first. */
    public List<String> lines(Claim claim) {
        return lines(claim.getSheetId()).getOrDefault(claim.getId(), List.of());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Stores the claim's new status and logs it, by the user, at its due then. */
public class SaveClaim {
    public void save(@Val StatusInput input, @Val Claim claim, ClaimStore store, ClaimLogStore log) {
        store.save(claim);
        log.record(claim, input.user());
    }
}
package net.officefloor.hq.app.claim;

/** Body of an OPEN claim's deferral, as sent: the date (yyyy-MM-dd) it is deferred until and who defers it. */
public record DeferRequest(String until, String user) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A validated deferral: the date the claim is deferred until and who defers it. */
public record DeferInput(LocalDate until, String user) {
}
-- Where a claim is listed among its person's claims, newest first: taken when it is added, and taken
-- anew when it is moved to another person, so it is listed as their newest claim whatever its date.
CREATE SEQUENCE claim_listed_seq;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
-- A claim's status log: one entry per status it has had, oldest first (by id), each with the user who
-- made the change, the sheet's today then, and the claim's due as computed at that moment (n/a when
-- no rate applied). Claims already kept have no entries.
CREATE TABLE claim_log (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255) NOT NULL,
    claim_id   BIGINT       NOT NULL,
    status     VARCHAR(16)  NOT NULL,
    by_user    VARCHAR(255) NOT NULL,
    log_date   DATE         NOT NULL,
    due        VARCHAR(32)  NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
